    public static String getSimpleName(String fqn) {
        if (fqn == null) return "";
        int lastDot = fqn.lastIndexOf('.');
        if (lastDot == -1) return fqn;
        return fqn.substring(lastDot + 1);
    }

    public static void main(String[] args) {
        System.out.println(getSimpleName("java.util.concurrent.atomic.AtomicInteger"));
        System.out.println(getSimpleName("OrderService"));
    }
