import java.util.*;

public class LangChecker {
    private static final Set<String> CORE_TYPES = new HashSet<>(Arrays.asList(
        "Object", "Class", "String", "StringBuilder", "StringBuffer",
        "Math", "System", "Thread", "Throwable", "Exception", "Error",
        "Integer", "Double", "Long", "Boolean", "Character", "Byte", "Short", "Float"
    ));

    public static boolean isJavaLangCore(String typeName) {
        if (typeName == null) return false;
        return CORE_TYPES.contains(typeName);
    }

    public static void main(String[] args) {
        System.out.println("String: " + isJavaLangCore("String"));
        System.out.println("ArrayList: " + isJavaLangCore("ArrayList"));
        System.out.println("Math: " + isJavaLangCore("Math"));
    }
}

