import java.util.*;

public class PackageValidator {
    private static final Set<String> KEYWORDS = new HashSet<>(Arrays.asList(
        "abstract", "assert", "boolean", "break", "byte", "case", "catch", "char",
        "class", "const", "continue", "default", "do", "double", "else", "enum",
        "extends", "final", "finally", "float", "for", "goto", "if", "implements",
        "import", "instanceof", "int", "interface", "long", "native", "new", "package",
        "private", "protected", "public", "return", "short", "static", "strictfp",
        "super", "switch", "synchronized", "this", "throw", "throws", "transient",
        "try", "void", "volatile", "while"
    ));

    public static boolean isValidPackageName(String pkg) {
        if (pkg == null || pkg.isEmpty() || pkg.startsWith(".") || pkg.endsWith(".")) {
            return false;
        }
        String[] parts = pkg.split("\\.");
        if (parts.length == 0) return false;
        for (String part : parts) {
            if (part.isEmpty() || KEYWORDS.contains(part)) return false;
            if (!Character.isJavaIdentifierStart(part.charAt(0))) return false;
            for (int i = 1; i < part.length(); i++) {
                if (!Character.isJavaIdentifierPart(part.charAt(i))) return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        System.out.println(isValidPackageName("com.learnbyself.core"));
        System.out.println(isValidPackageName("com.learn..core"));
        System.out.println(isValidPackageName("com.class.test"));
    }
}
